pm.test("B is reported as auto-rejected in the response", function () {
  var ids = pm.response.json().autoRejectedConflictingBookingIds || [];
  pm.expect(ids).to.include(pm.environment.get("bookingB"));
});

pm.test("B is rejected with a clear reason", function () {
  var b = pm.response.json().booking;
  pm.expect(b.status).to.eql("rejected");
  pm.expect(b.rejectionReason).to.match(/booked by another renter/);
});

pm.test("has a notification explaining why their request was rejected", function () {
  var n = pm.response.json().notifications;
  pm.expect(n.length).to.be.at.least(1);
  pm.expect(n[0].type).to.eql("booking_rejected_conflict");
});

