pm.test("two bookings created, cart now empty", function () {
  var j = pm.response.json();
  pm.expect(j.created.length).to.eql(2);
  pm.expect(j.failed.length).to.eql(0);
  pm.expect(j.cart.items.length).to.eql(0);
});

pm.test("B was auto-rejected as a side effect", function () {
  var ids = pm.response.json().autoRejectedConflictingBookingIds || [];
  pm.expect(ids).to.include(pm.environment.get("raceBookingB"));
});

pm.test("rejected with a clear reason", function () {
  var b = pm.response.json().booking;
  pm.expect(b.status).to.eql("rejected");
  pm.expect(b.rejectionReason).to.match(/overlapping dates/);
});

pm.test("has the rejection notification", function () {
  var n = pm.response.json().notifications;
  pm.expect(n.some(function (x) { return x.bookingId === pm.environment.get("raceBookingB"); })).to.eql(true);
});

pm.test("zero everything for a fresh signup", function () {
  var d = pm.response.json().dashboard;
  pm.expect(d.upcoming.count).to.eql(0);
  pm.expect(d.active.count).to.eql(0);
  pm.expect(d.completed.count).to.eql(0);
  pm.expect(d.totalSpent).to.eql(0);
  pm.expect(d.overdue.count).to.eql(0);
});

pm.test("has at least one completed rental with spend", function () {
  var d = pm.response.json().dashboard;
  pm.expect(d.completed.count).to.be.at.least(1);
  pm.expect(d.totalSpent).to.be.above(0);
});

pm.test("zero everything for a fresh signup", function () {
  var d = pm.response.json().dashboard;
  pm.expect(d.totalRequests).to.eql(0);
  pm.expect(d.requestedProducts).to.be.an('array').that.is.empty;
  pm.expect(d.inspectionsDue.count).to.eql(0);
});

pm.test("has at least one total request on record", function () {
  var d = pm.response.json().dashboard;
  pm.expect(d.totalRequests).to.be.at.least(1);
});

pm.test("every result belongs to that owner", function () {
  var items = pm.response.json().bookings;
  items.forEach(function (b) { pm.expect(b.ownerId).to.eql(pm.environment.get("ownerId")); });
});

pm.test("at least one notification, unread", function () {
  var j = pm.response.json();
  pm.expect(j.notifications.length).to.be.at.least(1);
  pm.expect(j.unreadCount).to.be.at.least(1);
  pm.environment.set("notificationId", j.notifications[0]._id);
});
